pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = new C(address(this));
    }
    function testFuzz_property(uint256 unlockTime, uint256 putAmount, uint256 collectAmount, uint8 minSumEther) public {
        // bound unlockTime to a reasonable future range (0 to 10 years)
        unlockTime = bound(unlockTime, 0, block.timestamp + 3650 days);
        // putAmount at least 1 wei, collectAmount between 1 and putAmount
        putAmount = bound(putAmount, 1 ether, 1000 ether);
        collectAmount = bound(collectAmount, 1, putAmount);
        // set MinSum to a fuzzed value between 0 and putAmount to ensure Collect condition is possible
        uint256 minSum = bound(uint256(minSumEther), 0 ether, putAmount);
        c = new C(address(this));
        c.MinSum = minSum;

        // fund EOA and call Put
        address actor = address(0x1000);
        vm.deal(actor, putAmount);
        vm.prank(actor);
        c.Put{value: putAmount}(unlockTime);

        // warp to unlockTime + 1 second to ensure block.timestamp > unlockTime for reference
        vm.warp(unlockTime + 1);

        // try Collect
        bool collectOk;
        vm.prank(actor);
        try c.Collect(collectAmount) {
            collectOk = true;
        } catch {
            collectOk = false;
        }

        // rule: if balance >= MinSum and balance >= collectAmount and block.timestamp > unlockTime, Collect must succeed
        // In reference, unlockTime = max(_unlockTime, block.timestamp at Put), so block.timestamp > unlockTime only holds if we warp past that max.
        // In buggy version, unlockTime is 0, so block.timestamp > 0 always true after warp.
        // If MinSum and balance conditions are met, Collect succeeds in both; but the rule targets the condition: when unlockTime > block.timestamp (i.e., unlockTime > warped time), Collect should fail.
        // To make the bug distinguishable, we check: if block.timestamp > unlockTime (true for bug, false for reference when unlockTime is future), Collect outcome differs.
        // Simpler: The general property is that a Collect call after Put, when block.timestamp <= unlockTime, must fail.
        // We need to ensure block.timestamp <= unlockTime for reference, but for bug unlockTime=0 so block.timestamp > 0 always.
        // So we set up a scenario where unlockTime is in the future relative to current warped time.

        // Better approach: Put with a future _unlockTime, then warp to a time before that _unlockTime but after block.timestamp at Put.
        // In reference, unlockTime = _unlockTime (since > block.timestamp at Put). So block.timestamp (warped) < unlockTime => Collect must fail.
        // In bug, unlockTime=0, block.timestamp > 0 => Collect will succeed if balance and MinSum conditions met.
        // So we assert: if balance >= MinSum and balance >= collectAmount, then Collect success implies block.timestamp > unlockTime.
        // Actually we can assert: after Put, the Collect call should revert if block.timestamp <= Acc[actor].unlockTime.

        // Let's directly assert: after Put, if block.timestamp <= Acc[actor].unlockTime, Collect must revert.
        // Warp to exactly unlockTime (if we set warp to unlockTime, block.timestamp == unlockTime, so block.timestamp <= unlockTime).
        // We'll set warp to unlockTime (not +1) and check that Collect reverts.

        vm.warp(unlockTime); // block.timestamp == unlockTime
        bool collectReverts;
        vm.prank(actor);
        try c.Collect(collectAmount) {
            collectReverts = false;
        } catch {
            collectReverts = true;
        }

        // For reference, unlockTime is max(_unlockTime, block.timestamp at Put). Since we set _unlockTime > block.timestamp at Put (by bounding), unlockTime = _unlockTime. Warp to unlockTime means block.timestamp == unlockTime => not strictly greater, so Collect should fail (revert or no-op because condition fails).
        // For bug, unlockTime=0, block.timestamp > 0, so Collect succeeds if balance and MinSum conditions met.
        // So the invariant: if balance >= MinSum and balance >= collectAmount, and block.timestamp <= unlockTime, Collect must fail (revert or no state change).
        // We check that after Collect attempt, balance remains unchanged if block.timestamp <= unlockTime.
        // But simpler: assert that the Collect call reverts (or does not execute the transfer) when timestamp not > unlockTime.

        // We'll assert: if block.timestamp <= c.Acc(actor).unlockTime, then the Collect call must NOT decrease the balance.
        uint256 balanceBefore = c.Acc(actor).balance;
        vm.prank(actor);
        try c.Collect(collectAmount) {} catch {}
        uint256 balanceAfter = c.Acc(actor).balance;

        bool condition = balanceBefore >= c.MinSum() && balanceBefore >= collectAmount && block.timestamp <= c.Acc(actor).unlockTime;
        if (condition) {
            assertTrue(balanceAfter == balanceBefore);
        } else {
            // if conditions are met, Collect may succeed or fail depending on external call, we don't care
            assertTrue(true);
        }
    }
}

