pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 unlockTime, uint256 amount, uint256 collectAmount) public {
        // Ensure collectAmount > 0 and amount >= MinSum so Collect is attempted
        vm.assume(collectAmount > 0);
        vm.assume(amount >= 1 ether);
        // Ensure unlockTime is in the future so reference would block Collect
        vm.assume(unlockTime > block.timestamp);

        address actor = address(0x1234);
        vm.deal(actor, amount);
        vm.prank(actor);
        c.Put{value: amount}(unlockTime);

        // In reference, unlockTime == unlockTime (future), Collect should revert.
        // In bug, unlockTime == 0 (past), Collect should succeed.
        vm.prank(actor);
        (bool success, ) = address(c).call(abi.encodeWithSignature("Collect(uint256)", collectAmount));
        // Reference reverts -> success == false, bug succeeds -> success == true
        assertTrue(!success);
    }
}

