pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 unlockTime, uint256 putAmount, uint256 collectAmount) public {
        // 1. Keep amounts reasonable and non-zero for balances
        bound(putAmount, 1 ether, 1000 ether);
        bound(collectAmount, 1 ether, putAmount);
        vm.assume(unlockTime >= 0);
        vm.assume(unlockTime <= block.timestamp + 365 days);

        // 2. Set up user with sufficient ETH for Put
        address user = address(0x1234);
        vm.deal(user, putAmount);
        vm.prank(user);
        c.Put{value: putAmount}(unlockTime);

        // Warp forward to give the contract a chance to observe the past unlockTime if set incorrectly
        vm.warp(block.timestamp + 1 days);

        bool collectSuccess = true;
        vm.prank(user);
        try c.Collect(collectAmount) {
            collectSuccess = true;
        } catch {
            collectSuccess = false;
        }

        // 3. Assert: Collect should only succeed when unlockTime was properly set >= block.timestamp at Put time.
        //    If unlockTime was set to a past value, Collect now succeeds immediately after warp.
        //    General invariant: if collectSuccess is true, then the stored unlockTime must have been >= block.timestamp at Put time.
        uint256 storedUnlockTime = c.Acc(user).unlockTime;
        assertTrue(!collectSuccess || storedUnlockTime >= block.timestamp - 1 days);
    }
}

