pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint96 _unlockTime, uint96 _putAmount, uint96 _collectAmount) public {
        // Bound amounts to reasonable ranges
        uint256 unlockTime = uint256(_unlockTime);
        uint256 putAmount = uint256(_putAmount);
        uint256 collectAmount = uint256(_collectAmount);

        // Ensure we have enough for Put to succeed and Collect to be attempted
        vm.assume(putAmount >= 1 ether); // Must meet MinSum
        vm.assume(collectAmount > 0 && collectAmount <= putAmount);

        // Setup actor with sufficient ether
        address actor = address(0x1234);
        vm.deal(actor, putAmount + 1 ether); // Extra for potential Collect gas

        // Execute Put with fuzzed unlockTime
        vm.prank(actor);
        c.Put{value: putAmount}(unlockTime);

        // Warp to after unlockTime to attempt Collect
        vm.warp(block.timestamp + 1 days + unlockTime + 1);

        // Record balances before Collect
        uint256 contractBalanceBefore = address(c).balance;
        uint256 accBalanceBefore = c.Acc(actor).balance;

        // Attempt Collect
        vm.prank(actor);
        try c.Collect(collectAmount) {
            // Collect succeeded
            uint256 contractBalanceAfter = address(c).balance;
            uint256 accBalanceAfter = c.Acc(actor).balance;

            // If Collect succeeded, contract balance must decrease exactly by collectAmount
            assertEq(contractBalanceBefore - contractBalanceAfter, collectAmount, "Contract balance should decrease by collected amount");
            assertEq(accBalanceBefore - accBalanceAfter, collectAmount, "Holder balance should decrease by collected amount");
        } catch {
            // Collect reverted, so balances should remain unchanged
            uint256 contractBalanceAfter = address(c).balance;
            uint256 accBalanceAfter = c.Acc(actor).balance;
            assertEq(contractBalanceBefore, contractBalanceAfter, "Contract balance should not change on revert");
            assertEq(accBalanceBefore, accBalanceAfter, "Holder balance should not change on revert");
        }
    }
}

