pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 topAmount, uint256 nestedAmount) public {
        // Admissible domain: non-zero amounts, no overflow
        vm.assume(topAmount > 0 && nestedAmount > 0);
        vm.assume(topAmount <= 100 ether && nestedAmount <= 100 ether);

        // Deploy an adversarial re-entrant caller whose receive() calls Put again
        ReentrantAttacker attacker = new ReentrantAttacker(c);

        // Fund the top-level call
        vm.deal(address(attacker), topAmount);

        // The attacker calls Put once; during that call the attacker will call Put again via its receive()
        vm.prank(address(attacker));
        attacker.attack{value: topAmount}(nestedAmount);

        // After the nested reentrant call completes, the attacker's Acc balance should not exceed
        // the total Ether it contributed (topAmount).
        // The invariant: address(c).balance >= sum of all Acc balances
        uint256 totalEther = address(c).balance;
        uint256 totalAccBal;
        totalAccBal += c.Acc(address(attacker));
        totalAccBal += c.Acc(address(this));
        // In the buggy version the attacker's balance can be inflated beyond the Ether it sent,
        // making totalAccBal > address(c).balance
        assertTrue(totalEther >= totalAccBal);
    }
}

contract ReentrantAttacker {
    C target;
    uint256 private nestedAmt;
    bool private reentered;

    constructor(C _target) {
        target = _target;
    }

    function attack(uint256 _nestedAmount) external payable {
        nestedAmt = _nestedAmount;
        // First Put call: deposits msg.value
        target.Put{value: msg.value}(0);
    }

    receive() external payable {
        if (!reentered) {
            reentered = true;
            // Reentrant call to Put using stored nestedAmt (no new Ether sent, msg.value=0)
            target.Put{value: 0}(nestedAmt);
        }
    }
}

