pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    function testFuzz_property(uint256 unlockTime, uint256 collectAmount, address actor) public {
        // 1. restrict domain to feasible values
        vm.assume(actor != address(0));
        collectAmount = bound(collectAmount, 1, 1000000 ether);
        unlockTime = bound(unlockTime, 1, type(uint64).max);
        // ensure unlockTime is in the future relative to the first Put call
        vm.warp(0);
        // 2. deploy an adversarial helper that reverts on receive to ensure the call path reaches the critical state change
        Reverter reverter = new Reverter();

        // give actor some ether
        vm.deal(actor, collectAmount + 1 ether);

        // first Put by actor (sets locked_ and resets it on success in reference)
        vm.prank(actor);
        c.Put{value: 1 ether}(unlockTime);

        // warp past unlockTime so Collect is allowed
        vm.warp(unlockTime + 1);

        // record balance before Collect
        uint256 balanceBefore = c.Acc(actor).balance;

        // attempt Collect to the adversarial reverter; we only care if the contract state updates (balance decreases)
        // In reference: nonReentrant_ modifier allows call, lock resets, Collect proceeds, external call fails but balance is subtracted
        // In bug: nonReentrant_ modifier never resets lock, so Collect reverts and balance stays unchanged
        vm.prank(actor);
        c.Collect(collectAmount);

        uint256 balanceAfter = c.Acc(actor).balance;

        // The property: after a Collect attempt, if the call itself didn't succeed transferring ether,
        // the reference contract still correctly subtracts the balance (because the low-level call revert is not handled),
        // but the buggy contract fails to subtract because it reverts before reaching the subtraction.
        // Actually, the reference: balance is subtracted even if low-level call fails, because it's inside an unchecked block after the call.
        // We test: For the reference, balanceAfter < balanceBefore (subtraction happened).
        // For the bug, balanceAfter == balanceBefore (no subtraction happened due to early revert of modifier).
        // Wait, if the low-level call in Collect reverts, the reference still subtracts? Yes, because `sub_uint256` is after the call without a require on success.
        // But the bug's modifier reverts the *entire* Collect, so balance isn't touched.
        // We construct the adversarial helper that *reverts* on receive to make the external call fail, ensuring the bug manifests as no balance change.
        assertTrue(balanceAfter < balanceBefore);
    }
}

contract Reverter {
    fallback() external payable {
        revert("Adversarial revert");
    }
}

